fn copyto<T: Copy>(dst: Vec<T>, src: Vec<T>, mask: Vec<bool>) -> Vec<T> {
    // Use iterator zipping to handle each triplet of elements
    // For each index, select src element if mask is true, else dst element
    dst.into_iter()
        .zip(src.into_iter())
        .zip(mask.into_iter())
        .map(|((d, s), m)| if m { s } else { d })
        .collect()
}